public class InnerConnectionTypeRestConfigurationFactory(Action<Humidifier.Glue.ConnectionTypeTypes.RestConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Glue.ConnectionTypeTypes.RestConfiguration>
{

    internal InnerConnectionTypeValidationEndpointConfigurationFactory ValidationEndpointConfigurationFactory { get; set; }

    internal InnerConnectionTypeSourceConfigurationFactory GlobalSourceConfigurationFactory { get; set; }

    protected override Humidifier.Glue.ConnectionTypeTypes.RestConfiguration Create()
    {
        var restConfigurationResult = CreateRestConfiguration();
        factoryAction?.Invoke(restConfigurationResult);

        return restConfigurationResult;
    }

    private Humidifier.Glue.ConnectionTypeTypes.RestConfiguration CreateRestConfiguration()
    {
        var restConfigurationResult = new Humidifier.Glue.ConnectionTypeTypes.RestConfiguration();

        return restConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Glue.ConnectionTypeTypes.RestConfiguration result)
    {
        base.CreateChildren(result);

        result.ValidationEndpointConfiguration ??= ValidationEndpointConfigurationFactory?.Build();
        result.GlobalSourceConfiguration ??= GlobalSourceConfigurationFactory?.Build();
    }

} // End Of Class

